import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { rankFiles, batchFiles, understand } from '../src/understand.js';
import { ceConfig } from '../src/dense.js';

// A repository whose history makes a ranking: hot.py changed often and lately, warm.py once lately,
// old.py long ago, plus a test file, a generated file and a file outside the area.
function repo() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'thinker-understand-'));
  const g = (args, date) => execFileSync('git', args, { cwd: dir, env: { ...process.env, GIT_AUTHOR_DATE: date, GIT_COMMITTER_DATE: date, GIT_AUTHOR_NAME: 't', GIT_AUTHOR_EMAIL: 't@t', GIT_COMMITTER_NAME: 't', GIT_COMMITTER_EMAIL: 't@t' }, stdio: 'ignore' });
  g(['init', '-q']);
  const commit = (files, date) => { for (const [f, body] of Object.entries(files)) { fs.mkdirSync(path.dirname(path.join(dir, f)), { recursive: true }); fs.writeFileSync(path.join(dir, f), body); } g(['add', '-A'], date); g(['commit', '-qm', 'c'], date); };
  commit({ 'pkg/old.py': 'def old():\n    return 0\n' }, '2026-03-01T00:00:00Z');
  for (let i = 0; i < 4; i++) commit({ 'pkg/hot.py': `class Hot:\n    def run(self):\n        return ${i}\n` }, `2026-09-2${i}T00:00:00Z`);
  commit({ 'pkg/warm.py': 'def warm():\n    return 1\n', 'tests/test_hot.py': 'def test_x():\n    pass\n', 'pkg/gen_pb2.py': '# Generated by the protocol buffer compiler.  DO NOT EDIT!\nX = 1\n', 'other/elsewhere.py': 'def e():\n    return 2\n' }, '2026-09-25T00:00:00Z');
  return dir;
}

test('the most recently changed code is read first; tests, generated files and other areas are left out', () => {
  const r = repo();
  const files = rankFiles(r, { top: 10 });
  assert.equal(files[0], 'pkg/hot.py');
  assert.ok(files.includes('pkg/warm.py') && files.includes('other/elsewhere.py'));
  assert.ok(!files.includes('tests/test_hot.py'), 'tests are not explained');
  assert.ok(!files.includes('pkg/gen_pb2.py'), 'generated code is not explained');
  assert.ok(!files.includes('pkg/old.py'), 'outside the 180-day window');
  assert.deepEqual(rankFiles(r, { top: 10, areas: ['pkg'] }).sort(), ['pkg/hot.py', 'pkg/warm.py'], 'inside the focus areas only');
  assert.deepEqual(rankFiles(r, { top: 1 }), ['pkg/hot.py']);
});

test('files are batched by directory, and a file too big for one call is read in parts with its outline', () => {
  const r = repo();
  fs.writeFileSync(path.join(r, 'pkg/big.py'), Array.from({ length: 400 }, (_, i) => `def f${i}():\n    return ${i}\n`).join(''));
  const b = batchFiles(r, ['pkg/hot.py', 'pkg/warm.py', 'other/elsewhere.py', 'pkg/big.py'], 1500);
  const pkg = b.filter(x => x.dir === 'pkg' && !x.body.join('').includes('outline'));
  assert.deepEqual(pkg[0].files, ['pkg/hot.py', 'pkg/warm.py'], 'small files of a directory share a call');
  const parts = b.filter(x => x.files[0] === 'pkg/big.py');
  assert.ok(parts.length > 1);
  for (const p of parts) assert.match(p.body[0], /outline of the whole file[\s\S]*def f399/);
  assert.ok(b.some(x => x.dir === 'other'));
});

test('understand writes notes read from the code, with instance views, and logs what it read and spent', async () => {
  const r = repo();
  const notesDir = fs.mkdtempSync(path.join(os.tmpdir(), 'thinker-understand-notes-'));
  process.env.THINKER_NOTES_DIR = notesDir;
  const { Store } = await import('../src/store.js');
  const store = new Store(r);
  const calls = [];
  const completeFn = async o => {
    calls.push(o);
    if (o.schema.properties.notes) return { json: { notes: [{ title: 'How Hot runs', kind: 'map', body: 'pkg/hot.py:Hot.run returns the iteration.', answers: ['Where does Hot run?'], applies: 'changing Hot', deps: [{ path: 'pkg/hot.py', symbol: 'Hot.run' }] }] }, tokens: { inputTokens: 1000, outputTokens: 100 }, usage: [{ input_tokens: 1000, output_tokens: 100 }] };  // as complete() answers under Codex
    return { json: { search: 'How Hot runs: Hot.run returns the iteration; covers the Hot runner and warm path.' }, usage: {} };
  };
  try {
    const seen = [];
    const res = await understand(store, { top: 10, areas: ['pkg'], model: 'm', completeFn, onProgress: (d, n, part) => seen.push(`${part} ${d}/${n}`) });
    assert.deepEqual(seen, ['reading code 1/1', 'instance views 1/1'], 'both passes report their progress, by name');
    assert.equal(res.files, 2); assert.equal(res.notes, 1); assert.equal(res.views, 1); assert.equal(res.tokens, 1100);
    const n = store.list()[0];
    assert.equal(n.source.type, 'understanding');
    assert.match(n.searchInstances, /Hot runner/);
    assert.equal(n.deps[0].path, 'pkg/hot.py');
    assert.ok(calls[0].prompt.includes('pkg/hot.py') && !calls[0].prompt.includes('other/elsewhere.py'));
    const log = fs.readFileSync(path.join(r, '.thinker', 'log.jsonl'), 'utf8').split('\n').filter(Boolean).map(l => JSON.parse(l)).find(e => e.op === 'understand');
    assert.deepEqual([log.files, log.saved, log.tokens], [2, 1, 1100]);
    const dry = await understand(store, { top: 10, dry: true, completeFn: () => { throw new Error('a dry run calls no model'); } });
    assert.equal(dry.files.length, 3);
  } finally { delete process.env.THINKER_NOTES_DIR; }
});

test('the cross-encoder scores by search text unless views are multi, by config or variable', () => {
  assert.equal(ceConfig(null).views, 'search');
  assert.equal(ceConfig({ config: () => ({ ce: { views: 'multi' } }) }).views, 'multi');
  process.env.THINKER_CE_VIEWS = 'multi';
  try { assert.equal(ceConfig(null).views, 'multi'); } finally { delete process.env.THINKER_CE_VIEWS; }
});
